/* (v4.56) Create new CV: first a large window with every template, filled in with an example CV,
   in four categories (Premium, Professional, Modern, Creative). Choosing one opens the Edit pages with that template.
   RichTplPick.open(onChoose) · close() · isOpen() */
(function () {
  'use strict';
  const Pdf = window.CVPdf;
  if (!Pdf) return;
  const tr = s => (window.RichI18n && window.RichI18n.t ? window.RichI18n.t(s) : s);
  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

  // the example CV shown in every template
  const SAMPLE = {
    fullName: 'Alex Morgan', firstName: 'Alex', lastName: 'Morgan', title: 'Sales Executive',
    phone: '+1 (555) 123-4567', email: 'alex.morgan@email.com', address: 'Austin, Texas, USA',
    nationality: 'American', dob: '1995-06-14', gender: 'Male', marital: 'Single', licence: 'Texas, Class C',
    summary: 'Friendly and target-driven sales executive with five years of experience in retail and business sales. Builds strong customer relationships, explains products clearly and closes deals with confidence. Looking for a role where hard work and teamwork are rewarded.',
    experience: [
      { title: 'Sales Executive', company: 'Blue Ocean Wireless Inc.', location: 'Austin, Texas', start: '2022-03', end: '', current: true,
        duties: 'Met and exceeded monthly sales targets by 15%\nManaged a portfolio of 120 business customers\nPrepared quotations and followed up every lead\nTrained new staff on products and customer service' },
      { title: 'Retail Sales Associate', company: 'Best Electronics', location: 'Dallas, Texas', start: '2019-07', end: '2022-02', current: false,
        duties: 'Helped customers choose the right products\nHandled cash, card payments and returns\nKept displays neat and fully stocked' }
    ],
    education: [
      { degree: 'Bachelor of Business Administration', school: 'University of Texas at Austin', location: 'Austin, USA', start: '2014-09', end: '2018-06', current: false, summary: 'Marketing and sales management', details: '' },
      { degree: 'High School Diploma', school: 'Lincoln High School', location: 'Dallas, USA', start: '2012-09', end: '2014-06', current: false, summary: 'Business, English, Maths', details: '' }
    ],
    skills: ['Customer service', 'Negotiation', 'CRM software', 'Product knowledge', 'Team work'],
    languages: [{ name: 'English', level: 'Native' }, { name: 'Spanish', level: 'Good' }, { name: 'French', level: 'Basic' }],
    certificates: [{ name: 'Professional Selling Skills', issuer: 'Sales Academy', year: '2021', summary: 'Two-day course in consultative selling' }],
    achievements: 'Salesperson of the year, 2023', hobbies: 'Reading, Football, Travelling',
    references: 'Available on request.'
  };

  // (v4.97) real example people (2 women, 2 men, white background): each template shows its own person and name
  const PEOPLE = [{"first": "Daniel", "last": "Carter", "g": "m", "img": "data:image/jpeg;base64,"}, {"first": "Emily", "last": "Johnson", "g": "f", "img": "data:image/jpeg;base64,"}, {"first": "James", "last": "Walker", "g": "m", "img": "data:image/jpeg;base64,"}, {"first": "Sophia", "last": "Martinez", "g": "f", "img": "data:image/jpeg;base64,"}];
  const imgCache = {};
  function personFor(id) {
    const all = Pdf.designs(), i = Math.max(0, all.findIndex(d => d.id === id));
    return PEOPLE[i % PEOPLE.length];
  }
  function personImg(p) {
    if (imgCache[p.img]) return imgCache[p.img];
    const im = new Image(); im.src = p.img;
    im.ready = (im.decode ? im.decode() : new Promise(r => { im.onload = im.onerror = r; })).catch(() => {});
    return (imgCache[p.img] = im);
  }
  // a simple person picture for the example photo
  let photoImg = null;
  function photo() {
    if (photoImg) return photoImg;
    // (v4.62) a smart head-and-shoulders portrait: dark suit, white shirt, tie, short neat hair
    const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 240">' +
      '<defs><linearGradient id="bg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#E9EEF5"/><stop offset="1" stop-color="#C9D3E2"/></linearGradient>' +
      '<linearGradient id="sk" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#EDBE9A"/><stop offset="1" stop-color="#DCA47E"/></linearGradient>' +
      '<linearGradient id="su" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#26355C"/><stop offset="1" stop-color="#18223E"/></linearGradient></defs>' +
      '<rect width="200" height="240" fill="url(#bg)"/>' +
      '<path d="M-6 240C-2 196 22 176 66 166L100 182L134 166C178 176 202 196 206 240Z" fill="url(#su)"/>' +
      '<path d="M82 150h36v22c0 10-8 16-18 16s-18-6-18-16z" fill="#CF9670"/>' +
      '<path d="M78 164L100 186L122 164L120 240H80Z" fill="#FFFFFF"/>' +
      '<path d="M82 158L100 184L90 192Z" fill="#F4F6FA" stroke="#D5DBE6" stroke-width="1"/><path d="M118 158L100 184L110 192Z" fill="#F4F6FA" stroke="#D5DBE6" stroke-width="1"/>' +
      '<path d="M94 182h12l-2 9h-8z" fill="#7A1528"/><path d="M96 191h8l5 34-9 11-9-11z" fill="#93203A"/>' +
      '<path d="M64 167L80 162L94 210L86 240L74 206Z" fill="#141C33"/><path d="M136 167L120 162L106 210L114 240L126 206Z" fill="#141C33"/>' +
      '<ellipse cx="59" cy="110" rx="7.5" ry="11" fill="#D9A07A"/><ellipse cx="141" cy="110" rx="7.5" ry="11" fill="#D9A07A"/>' +
      '<path d="M60 100c0-32 18-52 40-52s40 20 40 52c0 34-18 58-40 58s-40-24-40-58z" fill="url(#sk)"/>' +
      '<path d="M58 106c-5-42 16-64 44-64 26 0 44 18 40 62-3-14-8-24-14-28-6-12-30-14-46-6 6-2 14-2 20 0-18 2-32 12-38 24-3 4-5 8-6 12z" fill="#2B1F18"/>' +
      '<path d="M78 98q8-5 16 0M106 98q8-5 16 0" stroke="#3A2A20" stroke-width="3" fill="none" stroke-linecap="round"/>' +
      '<ellipse cx="86" cy="108" rx="4" ry="3.2" fill="#2E241E"/><ellipse cx="114" cy="108" rx="4" ry="3.2" fill="#2E241E"/>' +
      '<path d="M100 112c-2 8-4 13-1 15" stroke="#C48A66" stroke-width="2.2" fill="none" stroke-linecap="round"/>' +
      '<path d="M88 134q12 8 24 0" stroke="#A8604A" stroke-width="2.6" fill="none" stroke-linecap="round"/></svg>';
    photoImg = new Image();
    photoImg.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
    photoImg.ready = (photoImg.decode ? photoImg.decode() : new Promise(r => { photoImg.onload = photoImg.onerror = r; })).catch(() => {});
    return photoImg;
  }

  const ICONS = {
    Premium: '<path class="sp-fill" d="M4 9l4 3 4-6 4 6 4-3-1.6 9H5.6z"/><path d="M4 9l4 3 4-6 4 6 4-3-1.6 9H5.6zM6 20.5h12"/>',
    Professional: '<rect class="sp-fill" x="3.5" y="7.5" width="17" height="12" rx="2.4"/><rect x="3.5" y="7.5" width="17" height="12" rx="2.4"/><path d="M9 7.5V6a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v1.5M3.5 12.5h17"/>',
    Modern: '<path class="sp-fill" d="M12 3l2.2 5.8L20 11l-5.8 2.2L12 19l-2.2-5.8L4 11l5.8-2.2z"/><path d="M12 3l2.2 5.8L20 11l-5.8 2.2L12 19l-2.2-5.8L4 11l5.8-2.2z"/>',
    Creative: '<path class="sp-fill" d="M12 3a9 9 0 1 0 0 18c1.3 0 1.9-.9 1.9-1.9 0-1.3-1.1-1.8-1.1-2.9 0-1 .8-1.8 1.8-1.8h2.1A4.3 4.3 0 0 0 21 10.2C21 6.1 17 3 12 3z"/><path d="M12 3a9 9 0 1 0 0 18c1.3 0 1.9-.9 1.9-1.9 0-1.3-1.1-1.8-1.1-2.9 0-1 .8-1.8 1.8-1.8h2.1A4.3 4.3 0 0 0 21 10.2C21 6.1 17 3 12 3z"/>'
  };

  let root = null, cat = null, onChoose = null, io = null, want = null;
  const grids = {};

  function build() {
    root = document.createElement('div');
    root.className = 'tp-overlay';
    root.hidden = true;
    root.setAttribute('role', 'dialog');
    root.setAttribute('aria-modal', 'true');
    root.setAttribute('aria-labelledby', 'tpTitle');
    const cats = window.CVDesignCategories || ['Premium', 'Professional', 'Modern', 'Creative'];
    root.innerHTML =
      '<div class="tp-sheet">' +
        '<div class="tp-head"><i class="tp-grab" aria-hidden="true"></i>' +
          '<div class="tp-ttl"><h2 id="tpTitle">' + esc(tr('Choose your template')) + '</h2>' +
            '<p>' + esc(tr('Pick a look first. You can change the template and colours any time in Design.')) + '</p>' +
            '<button type="button" class="tp-skip"><span>' + esc(tr('Skip, choose later')) + '</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg></button></div>' +
          '<button type="button" class="tp-x" aria-label="' + esc(tr('Close')) + '"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button>' +
        '</div>' +
        '<div class="sp-tabs tp-tabs" role="tablist">' + cats.map(c =>
          '<button type="button" role="tab" data-tpcat="' + esc(c) + '" aria-selected="false"><svg viewBox="0 0 24 24" aria-hidden="true">' + (ICONS[c] || ICONS.Modern) + '</svg><span>' + esc(tr(c)) + '</span></button>').join('') +
        '</div>' +
        '<div class="tp-body"></div>' +
      '</div>';
    document.body.appendChild(root);
    root.querySelector('.tp-x').addEventListener('click', close);
    // (v4.68) drag the blue header down to close the window
    dragToClose(root.querySelector('.tp-head'), root.querySelector('.tp-sheet'));
    // (v4.61) skip: straight to the Edit pages with the usual template; it can be chosen later in Design
    root.querySelector('.tp-skip').addEventListener('click', () => { const cb = onChoose; if (cb) cb(null, { closePicker: close }); else close(); });   // (v4.95) the same loading card as choosing a template
    root.addEventListener('click', e => {
      const t = e.target.closest('[data-tpcat]');
      if (t) { show(t.dataset.tpcat); return; }
      const c = e.target.closest('[data-tpdesign]');
      if (c) choose(c.dataset.tpdesign, c);
    });
    // the page behind does not scroll or react while the window is open
    root.addEventListener('touchmove', e => { if (!e.target.closest('.tp-body')) e.preventDefault(); }, { passive: false });
    root.addEventListener('wheel', e => { if (!e.target.closest('.tp-body')) e.preventDefault(); }, { passive: false });
    document.addEventListener('keydown', e => { if (e.key === 'Escape' && isOpen() && !document.querySelector('.pm-overlay')) close(); });
    // after buying Pro: the Pro marks go away
    document.addEventListener('richpro', () => {
      if (!(window.RichPremium && window.RichPremium.isPremium())) return;
      badges();
      // the purchase was made from this window: open the Pro template the user tapped
      const id = want; want = null;
      const card = id && isOpen() && root.querySelector('[data-tpdesign="' + id + '"]');
      if (card) setTimeout(() => choose(id, card), 350);
    });
    if ('IntersectionObserver' in window) {
      io = new IntersectionObserver(list => list.forEach(en => { if (en.isIntersecting) { io.unobserve(en.target); draw(en.target); } }),
        { root: root.querySelector('.tp-body'), rootMargin: '300px 0px' });
    }
  }

  async function draw(card) {
    const id = card.dataset.tpdesign, ds = Pdf.designs().find(d => d.id === id), c = card.querySelector('canvas');
    if (!ds || !c || card.dataset.drawn) return;
    card.dataset.drawn = '1';
    try {
      await Pdf.loadFont(ds.font);
      const who = personFor(ds.id), img = personImg(who);
      await img.ready;
      const theme = Object.assign({}, Pdf.DEFAULT_THEME, { design: ds.id, color: ds.color, font: ds.font });
      const sample = Object.assign({}, SAMPLE, { firstName: who.first, lastName: who.last, fullName: who.first + ' ' + who.last,
        email: (who.first + '.' + who.last).toLowerCase() + '@email.com', gender: who.g === 'f' ? 'Female' : 'Male', photo: 'x', theme });
      const pages = Pdf.layout(sample, { hasPhoto: true, design: ds.id, theme });
      Pdf.drawToCanvas(pages[0], c, { photo: img }, Math.max(120, c.clientWidth || 160), 2);
      card.classList.add('is-drawn');
    } catch (e) { console.error(e); }
  }

  function show(c) {
    cat = c;
    root.querySelectorAll('[data-tpcat]').forEach(b => b.setAttribute('aria-selected', String(b.dataset.tpcat === c)));
    const body = root.querySelector('.tp-body');
    Object.keys(grids).forEach(k => { grids[k].hidden = k !== c; });
    if (!grids[c]) {
      const g = document.createElement('div');
      g.className = 'tp-grid';
      g.innerHTML = Pdf.designs().filter(d => d.category === c).map((d, i) => {
        return '<button type="button" class="tp-card" data-tpdesign="' + esc(d.id) + '" style="--i:' + Math.min(i, 12) + '">' +
          '<span class="tp-paper"><canvas aria-hidden="true"></canvas></span>' +
          '<span class="tp-name">' + esc(d.name) + '</span></button>';
      }).join('');
      body.appendChild(g);
      grids[c] = g;
      g.querySelectorAll('.tp-card').forEach(card => { if (io) io.observe(card); else draw(card); });
    }
    badges(grids[c]);
    body.scrollTop = 0;
  }
  // (v4.97) the corner badge of each card: "Pro", or "Free" with "Free for a limited time" for a template
  // unlocked with an ad in the last 6 hours (nothing for free templates or when Pro is bought)
  function badges(scope) {
    const P = window.RichPremium;
    (scope || root).querySelectorAll('.tp-card').forEach(card => {
      const id = card.dataset.tpdesign, paper = card.querySelector('.tp-paper');
      const pro = !!(P && P.isLocked && P.isLocked(id)), free = pro && !!(P.tplUnlockAt && P.tplUnlockAt(id));
      card.classList.toggle('is-free', free);
      let b = paper.querySelector('.tp-pro, .tp-free'); if (b) b.remove();
      let note = card.querySelector('.tp-freenote'); if (note) note.remove();
      if (!pro) return;
      b = document.createElement('em'); b.className = free ? 'tp-free' : 'tp-pro'; b.textContent = free ? 'Free' : 'Pro';
      paper.appendChild(b);
      if (free) { note = document.createElement('span'); note.className = 'tp-freenote'; note.textContent = 'Free for a limited time'; card.appendChild(note); }
    });
  }

  function choose(id, card) {
    // (v4.57) a Pro template without Pro: the upgrade screen, the template window stays open behind it
    const P = window.RichPremium;
    const freeAt = P && P.tplUnlockAt ? P.tplUnlockAt(id) : 0;
    if (P && P.isLocked && P.isLocked(id) && !(P.isPremium && P.isPremium()) && !freeAt) {
      try { if (navigator.vibrate) navigator.vibrate(8); } catch (e) { /* ignore */ }
      want = id;                                    // (v4.63) bought Pro from here: carry on with this template
      // (v4.96) or one rewarded ad: the template becomes free for ONE new CV (one template at a time: unlocking another
      // one takes it back). The picker stays open where it was: the card turns "Free"; tapping it then opens the form.
      if (P.offer) P.offer('template', { onReward: () => {
        want = null;
        P.tplUnlock(id);
        badges();
        const c = root.querySelector('.tp-card[data-tpdesign="' + id + '"]');
        if (c) { c.classList.remove('just-free'); void c.offsetWidth; c.classList.add('just-free'); }
        setTimeout(() => { if (window.RichApp) window.RichApp.toast('This template is now free for one CV. Tap it to use it.'); }, 350);
        return 'quiet';
      } });
      return;
    }
    card.classList.add('is-picked');
    try { if (window.AndroidBridge && AndroidBridge.haptic) AndroidBridge.haptic(); else if (navigator.vibrate) navigator.vibrate(8); } catch (e) { /* ignore */ }
    const cb = onChoose;
    // (v4.95) the app shows its loading card first, sets the template up behind it, then closes this window
    // (closing first left the screen frozen for a moment on slower phones)
    // a template unlocked with an ad: the new CV gets that unlock while it is being made (see openCV in app.js)
    const extra = freeAt && !(P.isPremium && P.isPremium()) ? { closePicker: close, unlock: true, unlockAt: freeAt } : { closePicker: close };
    if (extra.unlock && P.tplConsume) P.tplConsume(id);      // (v4.96) used up: the next new CV needs another ad
    setTimeout(() => { if (cb) cb(id, extra); else close(); }, 90);
  }

  function open(cb) {
    if (!root) build();
    onChoose = cb;
    root.hidden = false;
    document.documentElement.classList.add('no-scroll'); document.body.classList.add('no-scroll');
    requestAnimationFrame(() => root.classList.add('is-open'));
    // always opens on the first category (Premium)
    show((window.CVDesignCategories || ['Premium'])[0]);
    badges();
  }
  function dragToClose(handle, sheet) {
    let d = null;
    const y = e => (e.touches ? e.touches[0] : e).clientY;
    const start = e => {
      if (e.touches && e.touches.length > 1) return;
      d = { y0: y(e), t0: Date.now(), dy: 0, on: false };
    };
    const move = e => {
      if (!d) return;
      const dy = y(e) - d.y0;
      if (!d.on) { if (dy < 8) return; d.on = true; sheet.style.transition = 'none'; }
      d.dy = Math.max(0, dy);
      sheet.style.transform = 'translateY(' + d.dy + 'px)';
      root.style.background = 'rgba(6, 14, 38, ' + (0.55 * Math.max(0, 1 - d.dy / sheet.clientHeight)).toFixed(3) + ')';
      if (e.cancelable) e.preventDefault();
    };
    const end = () => {
      if (!d) return;
      const was = d; d = null;
      if (!was.on) return;
      // dragged far enough, or flicked down quickly: close; otherwise spring back
      const fast = was.dy / Math.max(1, Date.now() - was.t0) > 0.6;
      sheet.style.transition = 'transform .22s cubic-bezier(.2, .8, .2, 1)';
      root.style.background = '';
      if (was.dy > Math.min(160, sheet.clientHeight * 0.22) || (fast && was.dy > 40)) {
        sheet.style.transform = 'translateY(100%)';
        close();
      } else sheet.style.transform = '';
      // a drag is not a tap on the X or Skip button underneath
      const stop = ev => { ev.stopPropagation(); ev.preventDefault(); };
      handle.addEventListener('click', stop, { capture: true, once: true });
      setTimeout(() => handle.removeEventListener('click', stop, { capture: true }), 350);
    };
    handle.addEventListener('touchstart', start, { passive: true });
    handle.addEventListener('touchmove', move, { passive: false });
    handle.addEventListener('touchend', end);
    handle.addEventListener('touchcancel', end);
    // mouse: the pointer is captured only once a drag really starts, so a plain click still reaches the X / Skip buttons
    handle.addEventListener('pointerdown', e => { if (e.pointerType === 'mouse') start(e); });
    handle.addEventListener('pointermove', e => {
      if (e.pointerType !== 'mouse' || !d) return;
      move(e);
      if (d && d.on && !d.cap) { d.cap = true; try { handle.setPointerCapture(e.pointerId); } catch (x) { /* ignore */ } }
    });
    handle.addEventListener('pointerup', e => { if (e.pointerType === 'mouse') end(); });
  }
  function close() {
    if (!root || root.hidden) return;
    want = null;
    root.classList.remove('is-open');
    onChoose = null;
    setTimeout(() => {
      root.hidden = true;
      const sh = root.querySelector('.tp-sheet'); if (sh) { sh.style.transform = ''; sh.style.transition = ''; }
      root.style.background = '';
      root.querySelectorAll('.is-picked').forEach(x => x.classList.remove('is-picked'));
      if (!document.querySelector('.overlay:not([hidden])')) { document.documentElement.classList.remove('no-scroll'); document.body.classList.remove('no-scroll'); }
    }, 220);
  }
  const isOpen = () => !!(root && !root.hidden);

  window.RichTplPick = { open, close, isOpen };
})();
